@Test
public void testDenormsWithJoinsWithNoCandidateStorages() throws Exception {
    Configuration tconf = new Configuration(this.conf);
    tconf.set(CubeQueryConfUtil.DRIVER_SUPPORTED_STORAGES, "C1");
    LensException e = getLensExceptionInRewrite("select dim2big2, max(msr3)," + " msr2 from testCube" + " where " + TWO_DAYS_RANGE, tconf);
    NoCandidateFactAvailableException ne = (NoCandidateFactAvailableException) e;
    PruneCauses.BriefAndDetailedError error = ne.getJsonMessage();
    Assert.assertEquals(error.getBrief(), CandidateTablePruneCode.NO_CANDIDATE_STORAGES.errorFormat);
    HashMap<String, List<CandidateTablePruneCause>> details = error.getDetails();
    for (Map.Entry<String, List<CandidateTablePruneCause>> entry : details.entrySet()) {
        if (entry.getValue().equals(Arrays.asList(CandidateTablePruneCause.columnNotFound("dim2big2")))) {
            Set<String> expectedKeySet = Sets.newTreeSet(Splitter.on(',').split("summary1,cheapfact,testfactmonthly,testfact2,testfact"));
            Assert.assertTrue(expectedKeySet.equals(Sets.newTreeSet(Splitter.on(',').split(entry.getKey()))));
        }
        if (entry.getValue().equals(Arrays.asList(new CandidateTablePruneCause(CandidateTablePruneCode.INVALID_DENORM_TABLE)))) {
            Set<String> expectedKeySet = Sets.newTreeSet(Splitter.on(',').split("summary2,testfact2_raw,summary3"));
            Assert.assertTrue(expectedKeySet.equals(Sets.newTreeSet(Splitter.on(',').split(entry.getKey()))));
        }
        if (entry.getKey().equals("testfact_continuous")) {
            Assert.assertTrue(entry.getValue().equals(Arrays.asList(CandidateTablePruneCause.columnNotFound("msr2", "msr3"))) || entry.getValue().equals(Arrays.asList(CandidateTablePruneCause.columnNotFound("msr3", "msr2"))));
        }
        if (entry.getKey().equals("summary4")) {
            List<CandidateTablePruneCause> expectedPruneCauses = Arrays.asList(CandidateTablePruneCause.noCandidateStorages(new HashMap<String, CandidateTablePruneCause.SkipStorageCause>() {

                {
                    put("C2", new CandidateTablePruneCause.SkipStorageCause(CandidateTablePruneCause.SkipStorageCode.UNSUPPORTED));
                }
            }));
            Assert.assertTrue(entry.getValue().equals(expectedPruneCauses));
        }
    }
}

