    Assert.assertTrue(HQLParser.equalsAST(expr1, expr2));
    ASTNode literalExpr1 = HQLParser.parseExpr("A = 'FooBar'");
    ASTNode literalExpr2 = HQLParser.parseExpr("a = 'FooBar'");
