    // do post once again
    QueryHandle handle2 = target.path(pHandle.toString()).request(mt).post(Entity.entity(confpart, MediaType.MULTIPART_FORM_DATA_TYPE), QueryHandle.class);
    assertNotEquals(handle1, handle2);
    LensQuery ctx1 = waitForQueryToFinish(target(), lensSessionId, handle1, Status.SUCCESSFUL, mt);
    assertEquals(ctx1.getQueryName().toLowerCase(), "testquery1");
    LensQuery ctx2 = waitForQueryToFinish(target(), lensSessionId, handle2, Status.SUCCESSFUL, mt);
    assertEquals(ctx2.getQueryName().toLowerCase(), "testqueryname2");
    // destroy prepared
    APIResult result = target.path(pHandle.toString()).queryParam("sessionid", lensSessionId).request(mt).delete(APIResult.class);
    assertEquals(result.getStatus(), APIResult.Status.SUCCEEDED);
    // Post on destroyed query
    Response response = target.path(pHandle.toString()).request(mt).post(Entity.entity(confpart, MediaType.MULTIPART_FORM_DATA_TYPE), Response.class);
    assertEquals(response.getStatus(), 404);
}

