@Test
public void testTTLForInMemoryResult() throws InterruptedException, IOException, LensException {
    long inMemoryresultsetTTLMillisBackup = queryService.getInMemoryResultsetTTLMillis();
    // 5 secs
    queryService.setInMemoryResultsetTTLMillis(5000);
    try {
        // test post execute op
        final WebTarget target = target().path("queryapi/queries");
        final FormDataMultiPart mp = new FormDataMultiPart();
        LensConf conf = new LensConf();
        conf.addProperty(LensConfConstants.QUERY_PERSISTENT_RESULT_INDRIVER, "false");
        conf.addProperty(LensConfConstants.QUERY_PERSISTENT_RESULT_SET, "false");
        conf.addProperty(LensConfConstants.QUERY_MAIL_NOTIFY, "false");
        mp.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("sessionid").build(), lensSessionId, defaultMT));
        mp.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("query").build(), "select ID, IDSTR from " + TEST_TABLE));
        mp.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("operation").build(), "execute"));
        mp.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("conf").fileName("conf").build(), conf, defaultMT));
        final QueryHandle handle = target.request().post(Entity.entity(mp, MediaType.MULTIPART_FORM_DATA_TYPE), new GenericType<LensAPIResult<QueryHandle>>() {
        }).getData();
        assertNotNull(handle);
        waitForQueryToFinish(target(), lensSessionId, handle, Status.SUCCESSFUL, defaultMT);
        // Check TTL
        QueryContext ctx = queryService.getUpdatedQueryContext(lensSessionId, handle);
        long softExpiryTime = ctx.getDriverStatus().getDriverFinishTime() + queryService.getInMemoryResultsetTTLMillis() - //Keeping buffer of 1 secs
        1000;
        int checkCount = 0;
        while (System.currentTimeMillis() < softExpiryTime) {
            assertEquals(queryService.getFinishedQueriesCount(), 1);
            assertEquals(queryService.finishedQueries.peek().canBePurged(), false);
            assertEquals(((InMemoryResultSet) queryService.getResultset(handle)).canBePurged(), false);
            checkCount++;
            // sleep for 1 secs and then check again
            Thread.sleep(1000);
        }
        // TTl check at least twice
        assertTrue(checkCount >= 2, "CheckCount = " + checkCount);
        // should be past TTL after this sleep . purge thread runs every 1 secs for Tests
        Thread.sleep(3000);
        assertEquals(queryService.getFinishedQueriesCount(), 0);
    } finally {
        queryService.setInMemoryResultsetTTLMillis(inMemoryresultsetTTLMillisBackup);
    }
}

