@Test
public void testExponentialBackOff() {
    FailureContext failures = new FailureContext();
    BackOffRetryHandler retryHandler = OperationRetryHandlerFactory.createExponentialBackOffHandler(10, 10000, 1000);
    assertFalse(retryHandler.hasExhaustedRetries(failures));
    assertTrue(retryHandler.canTryOpNow(failures));
    long now = System.currentTimeMillis();
    failures.updateFailure();
    assertFalse(retryHandler.hasExhaustedRetries(failures));
    assertFalse(retryHandler.canTryOpNow(failures));
    assertTrue(now + 500 < retryHandler.getOperationNextTime(failures));
    assertTrue(now + 15000 > retryHandler.getOperationNextTime(failures));
    for (int i = 0; i < 10; i++) {
        failures.updateFailure();
    }
    assertTrue(retryHandler.hasExhaustedRetries(failures));
    assertFalse(retryHandler.canTryOpNow(failures));
    failures.clear();
    assertFalse(retryHandler.hasExhaustedRetries(failures));
    assertTrue(retryHandler.canTryOpNow(failures));
}

@Test
public void testMetricGauge() throws InterruptedException {
    Configuration conf = new Configuration();
    MethodMetricsContext mg = MethodMetricsFactory.createMethodGauge(conf, false, "nogauge");
    Assert.assertNotNull(mg);
    Assert.assertTrue(mg instanceof DisabledMethodMetricsContext);
    conf.set(LensConfConstants.QUERY_METRIC_UNIQUE_ID_CONF_KEY, "TestMethodMetricsFactory");
    conf.set(LensConfConstants.QUERY_METRIC_DRIVER_STACK_NAME, "TestMethodMetricsFactoryStackName");
    mg = MethodMetricsFactory.createMethodGauge(conf, false, "nostackgauge");
    Assert.assertNotNull(mg);
    Assert.assertTrue(mg instanceof MethodMetricGauge);
    Thread.sleep(1);
    mg.markSuccess();
    MetricRegistry reg = LensMetricsRegistry.getStaticRegistry();
    Assert.assertTrue(reg.getGauges().keySet().contains("lens.MethodMetricGauge.TestMethodMetricsFactory-nostackgauge"));
    // assert gauge value. It will be in nano seconds
    Assert.assertTrue(((Long) reg.getGauges().get("lens.MethodMetricGauge.TestMethodMetricsFactory-nostackgauge").getValue()) > 1000000);
    mg = MethodMetricsFactory.createMethodGauge(conf, true, "stackgauge");
    Assert.assertNotNull(mg);
    Thread.sleep(1);
    mg.markSuccess();
    Assert.assertTrue(reg.getGauges().keySet().contains("lens.MethodMetricGauge.TestMethodMetricsFactoryStackName-stackgauge"));
    Assert.assertTrue(((Long) reg.getGauges().get("lens.MethodMetricGauge.TestMethodMetricsFactoryStackName-stackgauge").getValue()) > 1000000);
}

