    Configuration conf = new Configuration();
    List<LensDriver> drivers = MockQueryContext.getDrivers(conf);
    MockQueryContext ctx = new MockQueryContext(drivers);
    String driverQuery = "driver query";
    ctx.setSelectedDriverQuery(driverQuery);
    assertNotNull(ctx.getSelectedDriverQuery());
    assertEquals(ctx.getSelectedDriverQuery(), driverQuery);
    assertEquals(ctx.getDriverQuery(ctx.getSelectedDriver()), driverQuery);
    ByteArrayOutputStream bios = new ByteArrayOutputStream();
    ObjectOutputStream out = new ObjectOutputStream(bios);
    byte[] ctxBytes = null;
    try {
        out.writeObject(ctx);
        ctxBytes = bios.toByteArray();
    } finally {
        out.close();
    }
    ByteArrayInputStream bais = new ByteArrayInputStream(ctxBytes);
    ObjectInputStream in = new ObjectInputStream(bais);
    MockQueryContext ctxRead = null;
    try {
        ctxRead = (MockQueryContext) in.readObject();
    } finally {
        in.close();
    }
    ctxRead.initTransientState();
    ctxRead.setConf(ctx.getConf());
    assertNotNull(ctxRead.getHiveConf());
    assertNotNull(ctxRead.getSelectedDriverQuery());
    assertEquals(ctxRead.getSelectedDriverQuery(), driverQuery);
    //Create DriverSelectorQueryContext by passing all the drivers and the user query
    DriverSelectorQueryContext driverCtx = new DriverSelectorQueryContext(ctxRead.getUserQuery(), ctxRead.getConf(), drivers);
    ctxRead.setDriverContext(driverCtx);
    ctxRead.getDriverContext().setSelectedDriver(ctx.getSelectedDriver());
    ctxRead.setDriverQuery(ctxRead.getSelectedDriver(), ctxRead.getSelectedDriverQuery());
    assertEquals(ctxRead.getDriverQuery(ctxRead.getSelectedDriver()), driverQuery);
}

@Test
public void testUpdateDriverStatusRetries() throws LensException {
    Configuration conf = new Configuration();
    List<LensDriver> drivers = MockQueryContext.getDrivers(conf);
    MockDriver selectedDriver = (MockDriver) drivers.iterator().next();
    MockQueryContext ctx = new MockQueryContext("simulate status retries", new LensConf(), conf, drivers);
    BackOffRetryHandler waitingHandler = new FibonacciExponentialBackOffRetryHandler(10, 10000, 1000);
    BackOffRetryHandler noWaitingHandler = new FibonacciExponentialBackOffRetryHandler(10, 0, 0);
    // do first update
    ctx.updateDriverStatus(waitingHandler);
    assertEquals(selectedDriver.getUpdateCount(), 1);
    // try another update, update should be skipped
    ctx.updateDriverStatus(waitingHandler);
    assertEquals(selectedDriver.getUpdateCount(), 1);
    // update without delays
    ctx.updateDriverStatus(noWaitingHandler);
    ctx.updateDriverStatus(noWaitingHandler);
    ctx.updateDriverStatus(noWaitingHandler);
    ctx.updateDriverStatus(noWaitingHandler);
    assertEquals(selectedDriver.getUpdateCount(), 5);
    // update with delays, update should be skipped
    ctx.updateDriverStatus(waitingHandler);
    assertEquals(selectedDriver.getUpdateCount(), 5);
    // update succeeds now.
    ctx.updateDriverStatus(noWaitingHandler);
    // all next updates should succeed, as retries should be cleared
    ctx.updateDriverStatus(waitingHandler);
    assertEquals(selectedDriver.getUpdateCount(), 7);
}

@Test
public void testUpdateDriverStatusRetrieExhausts() throws LensException {
    Configuration conf = new Configuration();
    List<LensDriver> drivers = MockQueryContext.getDrivers(conf);
    MockQueryContext ctx = new MockQueryContext("simulate status failure", new LensConf(), conf, drivers);
    BackOffRetryHandler waitingHandler = new FibonacciExponentialBackOffRetryHandler(10, 10000, 1000);
    BackOffRetryHandler noWaitingHandler = new FibonacciExponentialBackOffRetryHandler(10, 0, 0);
    for (int i = 0; i < 18; i++) {
        if (i % 2 == 0) {
            ctx.updateDriverStatus(noWaitingHandler);
        } else {
            ctx.updateDriverStatus(waitingHandler);
        }
    }
    // retries should be exhausted and update should fail.
    try {
        ctx.updateDriverStatus(noWaitingHandler);
        fail("Should throw exception");
    } catch (LensException e) {
        // pass
    }
}

@Test
public void testExceptionCauseMessage() {
    Throwable th = null;
    try {
        try {
            throw new IOException("base cause");
        } catch (IOException e) {
            throw new RuntimeException("run time exception", e);
        }
    } catch (Exception e) {
        th = e;
    }
    Assert.assertEquals(LensUtil.getCauseMessage(th), "base cause");
    // no message in base exception
    try {
        try {
            throw new IOException();
        } catch (IOException e) {
            throw new RuntimeException("run time exception", e);
        }
    } catch (Exception e) {
        th = e;
    }
    Assert.assertEquals(LensUtil.getCauseMessage(th), "run time exception");
}

@Test
public void testIds() {
    MappedDiagnosticLogSegregationContext testLogCtx = new MappedDiagnosticLogSegregationContext();
    String logId = "logid";
    testLogCtx.setLogSegregationId(logId);
    assertEquals(testLogCtx.getLogSegragationId(), logId);
    assertEquals(MDC.get(MappedDiagnosticLogSegregationContext.LOG_SEGREGATION_ID), logId);
    String queryId = "queryId";
    testLogCtx.setLogSegragationAndQueryId(queryId);
    assertEquals(testLogCtx.getQueryId(), queryId);
    assertEquals(testLogCtx.getLogSegragationId(), queryId);
    assertEquals(MDC.get(MappedDiagnosticLogSegregationContext.LOG_SEGREGATION_ID), queryId);
    assertEquals(MDC.get(MappedDiagnosticLogSegregationContext.QUERY_LOG_ID), queryId);
    String logId2 = "logid2";
    testLogCtx.setLogSegregationId(logId2);
    assertEquals(testLogCtx.getLogSegragationId(), logId2);
    assertEquals(MDC.get(MappedDiagnosticLogSegregationContext.LOG_SEGREGATION_ID), logId2);
    assertEquals(testLogCtx.getQueryId(), queryId);
    assertEquals(MDC.get(MappedDiagnosticLogSegregationContext.QUERY_LOG_ID), queryId);
    String queryId2 = "queryId2";
    testLogCtx.setQueryId(queryId2);
    assertEquals(testLogCtx.getQueryId(), queryId2);
    assertEquals(testLogCtx.getLogSegragationId(), logId2);
    assertEquals(MDC.get(MappedDiagnosticLogSegregationContext.LOG_SEGREGATION_ID), logId2);
    assertEquals(MDC.get(MappedDiagnosticLogSegregationContext.QUERY_LOG_ID), queryId2);
}

